create table if not exists public.course_ui(course_id uuid primary key references public.courses(id) on delete cascade,category text not null default 'STEM',level text not null default 'Начальный',cover_image text,is_optional boolean not null default false,featured boolean not null default false,sort_order integer not null default 100,updated_at timestamptz not null default now());
create table if not exists public.course_modules(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,title text not null,module_order integer not null default 1,unique(course_id,module_order));
create table if not exists public.lesson_content(lesson_id uuid primary key references public.lessons(id) on delete cascade,content_json jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists public.question_bank(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,question text not null,options jsonb not null,correct_index integer not null default 0,active boolean not null default true,created_at timestamptz not null default now(),unique(course_id,question));
create table if not exists public.course_resources(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,title text not null,description text,url text not null,resource_type text not null default 'Ссылка',sort_order integer not null default 100,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.optional_course_catalog(course_id uuid primary key references public.courses(id) on delete cascade,sort_order int not null default 100,active boolean not null default true,created_at timestamptz not null default now());
insert into public.course_ui(course_id,category,level,cover_image,is_optional) select c.id,v.category,v.level,v.cover,v.optional from public.courses c join (values ('labdisc','Лаборатория','Начальный','assets/course-covers/labdisc.svg',false),
('roqed-science','3D и наука','Начальный','assets/course-covers/roqed.svg',false),
('arduino','Электроника','Средний','assets/course-covers/arduino.svg',false),
('raspberry-pi-4','Программирование','Средний','assets/course-covers/raspberry.svg',false),
('flashforge-adventurer-5m-pro','3D-печать','Средний','assets/course-covers/flashforge.svg',false),
('ruida-rdworks8-medium','Цифровое производство','Средний','assets/course-covers/ruida.svg',false),
('lego-spike-prime','Робототехника','Начальный','assets/course-covers/spike.svg',false),
('bbc-microbit','Робототехника','Начальный','assets/course-covers/microbit.svg',true),
('scratch-basics','Программирование','Начальный','assets/course-covers/scratch.svg',true),
('python-stem','Программирование','Средний','assets/course-covers/python.svg',true),
('esp32-iot','Электроника и IoT','Продвинутый','assets/course-covers/esp32.svg',true),
('tinkercad-3d','3D-моделирование','Начальный','assets/course-covers/tinkercad.svg',true),
('autodesk-fusion','3D-моделирование','Продвинутый','assets/course-covers/fusion.svg',true),
('sketchup-3d','3D-моделирование','Средний','assets/course-covers/sketchup.svg',true)) v(slug,category,level,cover,optional) on v.slug=c.slug on conflict(course_id) do update set category=excluded.category,level=excluded.level,cover_image=excluded.cover_image,is_optional=excluded.is_optional,updated_at=now();
insert into public.optional_course_catalog(course_id,sort_order,active) select c.id,100,true from public.courses c join public.course_ui u on u.course_id=c.id where u.is_optional=true on conflict(course_id) do update set active=true;
insert into public.question_bank(course_id,question,options,correct_index,active) select c.id,'Для чего используется Labdisc?','["Для сбора и анализа экспериментальных данных", "Только для печати документов", "Только для просмотра видео", "Для создания презентаций"]'::jsonb,0,true from public.courses c where c.slug='labdisc' union all select c.id,'Какая программа используется для работы с данными Labdisc?','["GlobiLab X", "Paint", "PowerPoint", "Calculator"]'::jsonb,0,true from public.courses c where c.slug='labdisc' union all select c.id,'Какой способ подключения может использоваться с Labdisc?','["USB", "Только HDMI", "Только VGA", "Только Ethernet"]'::jsonb,0,true from public.courses c where c.slug='labdisc' union all select c.id,'Что измеряет датчик температуры?','["Температуру", "Освещённость", "Уровень звука", "Расстояние"]'::jsonb,0,true from public.courses c where c.slug='labdisc' union all select c.id,'Что нужно сделать перед началом эксперимента?','["Проверить устройство, заряд и необходимые датчики", "Сразу выключить Labdisc", "Удалить все данные", "Отключить все датчики"]'::jsonb,0,true from public.courses c where c.slug='labdisc' union all select c.id,'Для чего используется график после эксперимента?','["Для анализа изменения измеряемой величины", "Для украшения документа", "Для изменения пароля", "Для подключения USB"]'::jsonb,0,true from public.courses c where c.slug='labdisc' union all select c.id,'Что зависит от конкретной модели Labdisc?','["Набор доступных датчиков", "Название платформы STEM Trainer", "Цвет сайта", "Логин преподавателя"]'::jsonb,0,true from public.courses c where c.slug='labdisc' union all select c.id,'Какая модель Labdisc ориентирована на экологические исследования?','["Enviro", "Physio", "BioChem", "Arduino"]'::jsonb,0,true from public.courses c where c.slug='labdisc' union all select c.id,'Какая модель ориентирована на физические эксперименты?','["Physio", "Enviro", "BioChem", "Gensci Printer"]'::jsonb,0,true from public.course